import { drizzle } from 'drizzle-orm/postgres-js';
import postgres from 'postgres';

// Transaction pooler connection string (Port 6543)
// Add ?pgbouncer=true or prepare=false to prevent prepared statement errors
const connectionString = process.env.DATABASE_URL!;

// Configure client with max 1 connection per serverless function instance
const client = postgres(connectionString, {
  max: 1,
  idle_timeout: 20,
  connect_timeout: 10,
  prepare: false, // Required for PgBouncer / Supabase transaction mode
});

export const db = drizzle(client);
